export function worksheet(name) { return `CLUBE DE REVISTA — ${name}

1. Pergunta PICO e horizonte:

2. Desfecho primário e estimando:

3. Magnitude, unidade e intervalo de confiança:

4. Eventos adversos, interrupções e dados ausentes:

5. Principal limitação e aplicabilidade:

6. Minha conclusão em uma frase:

7. Dúvida que depende do artigo/suplemento:

`; }
